package com.vioverlord.java17trainer;

import android.app.*;import android.os.*;import android.content.*;import android.graphics.Typeface;import android.view.*;import android.widget.*;import java.util.*;

public class MainActivity extends Activity{
  String lang="zh"; ArrayList<Q> bank=new ArrayList<>(), run=new ArrayList<>(); int idx=0, ok=0, chosenStage=0; long endAt=0; LinearLayout root;
  String[] stZh={"基础声明与变量","类型转换与字符串","流程控制","数组与集合","方法与构造器","继承与多态","异常与常用API"};
  String[] stJa={"基本宣言と変数","型変換と文字列","制御構文","配列とコレクション","メソッドとコンストラクタ","継承とポリモーフィズム","例外と基本API"};
  public void onCreate(Bundle b){super.onCreate(b); lang=getPreferences(0).getString("lang","zh"); buildBank(); home();}
  TextView tv(String s,int sp,int style){TextView v=new TextView(this);v.setText(s);v.setTextSize(sp);v.setTypeface(Typeface.DEFAULT,style);v.setPadding(8,8,8,8);root.addView(v);return v;}
  Button btn(String s){Button b=new Button(this);b.setText(s);root.addView(b);return b;}
  void page(){ScrollView sv=new ScrollView(this);root=new LinearLayout(this);root.setOrientation(LinearLayout.VERTICAL);root.setPadding(28,28,28,28);sv.addView(root);setContentView(sv);} String L(String z,String j){return "ja".equals(lang)?j:z;} String stageName(int i){return "ja".equals(lang)?stJa[i]:stZh[i];}
  void home(){page();tv("Java Silver 17 Trainer",26,Typeface.BOLD);tv(L("840道原创变体题｜不是背原题，是靠理解刷全知识点","840問のオリジナル変形問題｜暗記ではなく理解で解く"),15,0);tv(L("当前阶段：","現在のステージ：")+stageName(chosenStage),16,Typeface.BOLD);btn(L("切换中文/日本語","中文/日本語 切替")).setOnClickListener(v->{lang="zh".equals(lang)?"ja":"zh";getPreferences(0).edit().putString("lang",lang).apply();home();});btn(L("选择大纲阶段","ステージ選択")).setOnClickListener(v->pickStage());btn(L("按当前大纲练习 120题","現在ステージで練習 120問")).setOnClickListener(v->start(0,chosenStage));btn(L("当前大纲随机 40题","現在ステージからランダム 40問")).setOnClickListener(v->start(1,chosenStage));btn(L("全范围随机 50题","全範囲ランダム 50問")).setOnClickListener(v->start(2,-1));btn(L("正式模拟考试 80题 / 180分钟","本番模擬試験 80問 / 180分")).setOnClickListener(v->start(3,-1));btn(L("Java关键字中日查询","Javaキーワード中日検索")).setOnClickListener(v->keywords());btn(L("成绩与弱项统计","成績と弱点分析")).setOnClickListener(v->stats());}
  void pickStage(){new AlertDialog.Builder(this).setItems("ja".equals(lang)?stJa:stZh,(d,which)->{chosenStage=which;home();}).show();}
  void start(int mode,int stage){run.clear();for(Q q:bank)if(stage<0||q.stage==stage)run.add(q);if(mode!=0)Collections.shuffle(run);int limit=mode==0?run.size():mode==1?40:mode==2?50:80;while(run.size()>limit)run.remove(run.size()-1);idx=0;ok=0;endAt=mode==3?System.currentTimeMillis()+180L*60L*1000L:0;showQ();}
  void showQ(){if(idx>=run.size()){finishRun();return;}page();Q q=run.get(idx);tv(L("第 ","第 ")+(idx+1)+" / "+run.size()+"    "+L("正确：","正解：")+ok,16,Typeface.BOLD);if(endAt>0)tv(L("剩余约：","残り約：")+Math.max(0,(endAt-System.currentTimeMillis())/60000)+L(" 分钟"," 分"),14,0);tv("["+stageName(q.stage)+"]  "+q.type+" / "+q.diff+" / "+q.tag,13,0);tv(q.text(),18,Typeface.BOLD);ArrayList<CheckBox> boxes=new ArrayList<>();for(int i=0;i<q.optsZ.length;i++){CheckBox cb=new CheckBox(this);cb.setText((char)('A'+i)+". "+q.opt(i));cb.setTextSize(16);final CheckBox me=cb;if(q.single)cb.setOnClickListener(v->{if(me.isChecked())for(CheckBox x:boxes)if(x!=me)x.setChecked(false);});boxes.add(cb);root.addView(cb);}Button sub=btn(L("提交并查看讲解","提出して解説を見る"));Button back=btn(L("返回主页","ホームへ戻る"));back.setOnClickListener(v->home());sub.setOnClickListener(v->{HashSet<Integer> s=new HashSet<>();for(int i=0;i<boxes.size();i++)if(boxes.get(i).isChecked())s.add(i);boolean good=s.equals(q.ans);if(good)ok++;mark(q,good);for(CheckBox c:boxes)c.setEnabled(false);sub.setEnabled(false);tv(good?L("正确","正解"):L("错误","不正解"),20,Typeface.BOLD);tv(L("正确答案：","正解：")+q.answerText(),16,Typeface.BOLD);tv(q.exp(),16,0);btn(idx+1>=run.size()?L("查看本轮结果","今回の結果を見る"):L("下一题","次の問題")).setOnClickListener(n->{idx++;showQ();});});}
  void finishRun(){page();tv(L("本轮完成","今回終了"),26,Typeface.BOLD);int total=run.size();tv(L("得分：","スコア：")+ok+" / "+total+"  " +(total==0?0:ok*100/total)+"%",22,Typeface.BOLD);HashMap<Integer,int[]> byS=new HashMap<>();HashMap<String,int[]> byT=new HashMap<>();for(int i=0;i<run.size();i++){Q q=run.get(i);int[] a=byS.containsKey(q.stage)?byS.get(q.stage):new int[2];a[0]++;byS.put(q.stage,a);int[] b=byT.containsKey(q.type)?byT.get(q.type):new int[2];b[0]++;byT.put(q.type,b);}tv(L("本轮出题分布：","今回の出題分布："),18,Typeface.BOLD);for(Integer s:byS.keySet())tv(stageName(s)+"  "+byS.get(s)[0]+L("题","問"),15,0);for(String t:byT.keySet())tv(t+"  "+byT.get(t)[0]+L("题","問"),15,0);btn(L("回主页","ホームへ")).setOnClickListener(v->home());}
  void stats(){page();SharedPreferences p=getPreferences(0);int t=p.getInt("allT",0),c=p.getInt("allC",0);tv(L("累计成绩","累計成績"),25,Typeface.BOLD);tv(L("总正确率：","総合正答率：")+c+" / "+t+"  "+(t==0?0:c*100/t)+"%",20,Typeface.BOLD);tv(L("按大纲：","ステージ別："),18,Typeface.BOLD);for(int i=0;i<7;i++){int tt=p.getInt("s"+i+"T",0),cc=p.getInt("s"+i+"C",0);tv(stageName(i)+"  "+cc+"/"+tt+"  "+(tt==0?0:cc*100/tt)+"%",15,0);}tv(L("按题型：","問題形式別："),18,Typeface.BOLD);String[] types={"SINGLE","MULTIPLE","EXECUTION","SELECT_CORRECT","SELECT_INCORRECT","CONCEPT"};for(String x:types){int tt=p.getInt("t"+x+"T",0),cc=p.getInt("t"+x+"C",0);tv(x+"  "+cc+"/"+tt+"  "+(tt==0?0:cc*100/tt)+"%",15,0);}btn(L("回主页","ホームへ")).setOnClickListener(v->home());}
  void mark(Q q,boolean good){SharedPreferences.Editor e=getPreferences(0).edit();inc(e,"allT");if(good)inc(e,"allC");inc(e,"s"+q.stage+"T");if(good)inc(e,"s"+q.stage+"C");inc(e,"t"+q.type+"T");if(good)inc(e,"t"+q.type+"C");e.apply();}
  void inc(SharedPreferences.Editor e,String k){SharedPreferences p=getPreferences(0);e.putInt(k,p.getInt(k,0)+1);} 
  void keywords(){page();tv(L("Java关键字中日查询","Javaキーワード中日検索"),24,Typeface.BOLD);String[][] ks={{"class","类声明","クラス宣言"},{"interface","接口","インターフェース"},{"extends","继承父类","親クラスを継承"},{"implements","实现接口","インターフェースを実装"},{"static","属于类本身","クラス自体に属する"},{"final","不可再赋值/继承/重写","再代入・継承・オーバーライド不可"},{"abstract","抽象","抽象"},{"public","公开访问","公開アクセス"},{"private","类内访问","クラス内アクセス"},{"protected","包内和子类访问","パッケージ内とサブクラス"},{"void","无返回值","戻り値なし"},{"return","返回","戻る"},{"if","条件分支","条件分岐"},{"switch","多分支","多分岐"},{"for","循环","繰り返し"},{"while","循环","繰り返し"},{"break","跳出","抜ける"},{"continue","进入下一轮","次の反復へ"},{"try","异常处理块","例外処理ブロック"},{"catch","捕获异常","例外を捕捉"},{"finally","最后执行","最後に実行"},{"throw","抛出异常","例外を投げる"},{"throws","声明可能抛出","例外送出を宣言"},{"new","创建对象","オブジェクト生成"},{"this","当前对象","現在のオブジェクト"},{"super","父类成员/构造器","親クラスのメンバー/コンストラクタ"},{"var","局部变量类型推断","ローカル変数型推論"},{"record","不可变数据载体","不変データキャリア"}};for(String[] k:ks)tv(k[0]+" : "+L(k[1],k[2]),15,0);btn(L("回主页","ホームへ")).setOnClickListener(v->home());}
  void buildBank(){if(!bank.isEmpty())return;for(int s=0;s<7;s++)for(int i=1;i<=120;i++)bank.add(make(s,i));}
  Q make(int s,int i){int k=i%12,n=i%9+1;String id="S"+(s+1)+"-"+i;switch(k){case 0:return q(s,"EXECUTION",n%3+1,"numeric",id+" 下列代码的结果是？\nint a="+(n+1)+"; double d=a/2; System.out.println(d);",id+" 次のコードの結果は？\nint a="+(n+1)+"; double d=a/2; System.out.println(d);",new String[]{((n+1)/2)+".0",((n+1)/2.0)+"","编译错误","运行时异常"},new String[]{((n+1)/2)+".0",((n+1)/2.0)+"","コンパイルエラー","実行時例外"},0,"a/2 先按 int 除法计算，再扩大为 double。","a/2 は先に int 除算され、その後 double に拡大される。");case 1:return q(s,"SINGLE",1,"String",id+" String s=\"Ja\"+\"va\"; 下面说法正确的是？",id+" String s=\"Ja\"+\"va\"; 正しい説明は？",new String[]{"编译期常量拼接","一定运行时拼接","不能用于 switch","结果不是 String"},new String[]{"コンパイル時定数として連結される","必ず実行時に連結される","switchで使えない","結果はStringではない"},0,"字符串字面量之间的 + 可在编译期合并。","文字列リテラル同士の + はコンパイル時に結合される。");case 2:return q(s,"SELECT_INCORRECT",2,"control",id+" 关于 switch，选错误的一项。",id+" switchについて誤りを選べ。",new String[]{"case 标签不能重复","default 位置可以不在最后","break 不是必须的","long 可以作为传统 switch 选择表达式"},new String[]{"caseラベルは重複不可","defaultは最後でなくてもよい","breakは必須ではない","longは従来switchの選択式に使える"},3,"传统 switch 支持 byte/short/char/int、包装类、String、enum 等，不支持 long。","従来switchは long を選択式に使えない。");case 3:return q(s,"EXECUTION",2,"array",id+" int[] a=new int["+(n+2)+"]; System.out.println(a[0]); 输出？",id+" int[] a=new int["+(n+2)+"]; System.out.println(a[0]); 出力は？",new String[]{"0","null","编译错误","ArrayIndexOutOfBoundsException"},new String[]{"0","null","コンパイルエラー","ArrayIndexOutOfBoundsException"},0,"int 数组元素默认值是 0。","int配列要素のデフォルト値は0。");case 4:return q(s,"MULTIPLE",3,"method",id+" 关于重载，选所有正确项。",id+" オーバーロードについて正しいものをすべて選べ。",new String[]{"参数列表不同可以重载","只改返回值不能重载","可变参数只能有一个且必须最后","private 方法不能重载"},new String[]{"引数リストが違えば可能","戻り値だけでは不可","可変長引数は1つだけで最後","privateメソッドはオーバーロード不可"},new int[]{0,1,2},"重载看方法名和参数列表，和返回值、访问修饰符无关。","オーバーロードは名前と引数リストで決まり、戻り値やアクセス修飾子だけでは決まらない。");case 5:return q(s,"SINGLE",2,"constructor",id+" 构造器第一行可以写什么？",id+" コンストラクタの先頭行に書けるものは？",new String[]{"this(...) 或 super(...)","return 值","任意普通语句再写 super(...) ","static 语句"},new String[]{"this(...) または super(...)","値をreturn","通常文の後にsuper(...)を書く","static文"},0,"构造器调用 this(...) 或 super(...) 时必须是第一条语句，且二者不能同时出现。","this(...) / super(...) は先頭文で、同時には使えない。");case 6:return q(s,"EXECUTION",3,"polymorphism",id+" Parent p=new Child(); p.run(); 调用哪个方法？",id+" Parent p=new Child(); p.run(); どのメソッドが呼ばれる？",new String[]{"Child 重写后的 run","Parent 的 run","编译错误","随机决定"},new String[]{"Childでオーバーライドしたrun","Parentのrun","コンパイルエラー","ランダム"},0,"实例方法运行时看实际对象类型，这是多态。","インスタンスメソッドは実行時の実体型で決まる。これがポリモーフィズム。");case 7:return q(s,"SELECT_CORRECT",2,"exception",id+" 关于 finally，选正确项。",id+" finallyについて正しいものを選べ。",new String[]{"通常无论是否异常都会执行","catch 必须至少两个","finally 不能和 try 单独使用","finally 一定能阻止程序结束"},new String[]{"通常は例外有無に関係なく実行","catchは必ず2つ以上","finallyはtryと単独で使えない","必ず終了を防ぐ"},0,"finally 通常会执行，但 JVM 强制结束等极端情况除外。","finallyは通常実行されるが、JVM強制終了などは例外。");case 8:return q(s,"CONCEPT",1,"list",id+" ArrayList 的 size() 表示什么？",id+" ArrayListのsize()は何を表す？",new String[]{"当前元素个数","底层数组容量","最大容量","最后一个下标"},new String[]{"現在の要素数","内部配列容量","最大容量","最後の添字"},0,"size() 是元素个数，最后下标是 size()-1。","size()は要素数。最後の添字はsize()-1。");case 9:return q(s,"MULTIPLE",2,"keyword",id+" 关于 final，选所有正确项。",id+" finalについて正しいものをすべて選べ。",new String[]{"final 变量不能再次赋值","final 类不能被继承","final 方法不能被重写","final 对象的内部状态一定不能变"},new String[]{"final変数は再代入不可","finalクラスは継承不可","finalメソッドはオーバーライド不可","final参照先の内部状態は必ず不変"},new int[]{0,1,2},"final 修饰引用时，引用不能换，但对象内部状态是否可变取决于类本身。","final参照は差し替え不可だが、内部状態の可変性はクラス次第。");case 10:return q(s,"SINGLE",2,"scope",id+" 局部变量在使用前必须怎样？",id+" ローカル変数は使用前に何が必要？",new String[]{"必须明确赋值","自动为 null","自动为 0","只能声明为 final"},new String[]{"明示的な代入が必要","自動的にnull","自動的に0","final限定"},0,"局部变量没有默认值，使用前必须确定已赋值。","ローカル変数にはデフォルト値がなく、使用前に代入が必要。");default:return q(s,"EXECUTION",3,"loop",id+" int x=0; for(int j=0;j<"+n+";j++){ if(j%2==0) x++; } 输出 x？",id+" int x=0; for(int j=0;j<"+n+";j++){ if(j%2==0) x++; } xの出力は？",new String[]{String.valueOf((n+1)/2),String.valueOf(n/2),String.valueOf(n),"编译错误"},new String[]{String.valueOf((n+1)/2),String.valueOf(n/2),String.valueOf(n),"コンパイルエラー"},0,"0 到 n-1 中偶数个数是 (n+1)/2。","0からn-1までの偶数の数は (n+1)/2。");}}
  Q q(int s,String type,int diff,String tag,String z,String j,String[] oz,String[] oj,int ans,String ez,String ej){return new Q(s,type,diff,tag,z,j,oz,oj,new int[]{ans},ez,ej);} Q q(int s,String type,int diff,String tag,String z,String j,String[] oz,String[] oj,int[] ans,String ez,String ej){return new Q(s,type,diff,tag,z,j,oz,oj,ans,ez,ej);} 
  class Q{int stage,diff;String type,tag,z,j,ez,ej;String[] optsZ,optsJ;HashSet<Integer> ans=new HashSet<>();boolean single;Q(int s,String t,int d,String g,String z,String j,String[] oz,String[] oj,int[] a,String ez,String ej){stage=s;type=t;diff=d;tag=g;this.z=z;this.j=j;optsZ=oz;optsJ=oj;for(int x:a)ans.add(x);single=a.length==1;this.ez=ez;this.ej=ej;}String text(){return L(z,j);}String opt(int i){return "ja".equals(lang)?optsJ[i]:optsZ[i];}String exp(){return L(ez,ej);}String answerText(){StringBuilder b=new StringBuilder();for(int i:ans){if(b.length()>0)b.append(", ");b.append((char)('A'+i));}return b.toString();}}
}
